#!/usr/bin/env node
/**
 * Build `src/components/render/render.generated.ts` from KaTeX and Pele.
 *
 * An answer can hold a block of math or a Mermaid diagram. The app draws them
 * in a web view, as the desktop app does with the same two libraries. The web
 * view gets them as text inside its page, not from a network: a diagram draws
 * with no connection, and nothing outside the app can change the code. The
 * fonts of KaTeX go in as data (woff2 only), for the same reason.
 *
 *   node scripts/vendor-render.mjs
 *
 * Run it again after an update of `katex` or `pele`.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { dirname, join, resolve } from 'node:path'

const require = createRequire(import.meta.url)
const katexDir = dirname(require.resolve('katex/package.json'))
const peleDir = dirname(require.resolve('pele/package.json'))
const version = dir => JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8')).version

// Each font in woff2, as data. The other formats are for old browsers: the rule keeps only the first source.
const css = readFileSync(join(katexDir, 'dist/katex.min.css'), 'utf8').replace(/src:url\(fonts\/([^)]+\.woff2)\) format\("woff2"\)[^;}]*/g, (_, file) => {
  const data = readFileSync(join(katexDir, 'dist/fonts', file)).toString('base64')

  return `src:url(data:font/woff2;base64,${data}) format("woff2")`
})

const parts = {
  KATEX_JS: readFileSync(join(katexDir, 'dist/katex.min.js'), 'utf8'),
  KATEX_CSS: css,
  PELE_JS: readFileSync(join(peleDir, 'dist/pele.global.js'), 'utf8')
}

// A script inside a <script> tag must not hold "</script": it would end the tag.
const safe = text => text.replace(/<\/script/gi, '<\\/script').replace(/\/\/# sourceMappingURL=.*$/gm, '')

const body = Object.entries(parts)
  .map(([name, text]) => `export const ${name}: string = ${JSON.stringify(safe(text))}`)
  .join('\n\n')

const target = resolve(import.meta.dirname, '../src/components/render/render.generated.ts')

writeFileSync(target, `// GENERATED by scripts/vendor-render.mjs from katex ${version(katexDir)} and pele ${version(peleDir)}. Do not edit by hand.\n\n${body}\n`)
console.log(`Wrote ${target}`)
